<?php
declare(strict_types=1);
$analyticsError = ''; $report = null;
try {
    $filters = mm_measurement_filters($_GET);
    $report = \Velvet\Core\MarketingStore::savedMeasurementReport($filters, ROOT_PATH);
    $analyticsConfiguration = $report['configuration'];
} catch (Throwable $caught) { $analyticsError = $caught instanceof RuntimeException || $caught instanceof InvalidArgumentException ? $caught->getMessage() : 'Measurement reporting is temporarily unavailable.'; }
mm_measurement_authorize();
?>
<section class="marketing-card" data-consented-analytics>
<h2>Consented measurement</h2>
<p>Only visitors who explicitly allow measurement enter these reports. Newsletter consent is separate. Legacy events without a verified measurement choice are excluded. All report dates are UTC calendar days.</p>
<form method="get" class="marketing-form"><input type="hidden" name="page" value="marketing"><input type="hidden" name="tab" value="analytics"><div class="marketing-admin-grid">
<label>Start date (UTC)<input type="date" name="start" value="<?= velvet_marketing_escape(mm_form_text($_GET['start'] ?? gmdate('Y-m-d', time() - 29 * 86400), 10)) ?>" required></label>
<label>End date (UTC)<input type="date" name="end" value="<?= velvet_marketing_escape(mm_form_text($_GET['end'] ?? gmdate('Y-m-d'), 10)) ?>" required></label>
<label>Campaign ID (optional)<input name="campaign" maxlength="80" value="<?= velvet_marketing_escape(mm_form_text($_GET['campaign'] ?? '', 80)) ?>"></label>
<label>Referral code (optional)<input name="referral" maxlength="64" value="<?= velvet_marketing_escape(mm_form_text($_GET['referral'] ?? '', 64)) ?>"></label>
<label>Event<select name="event"><option value="">All measured events</option><?php foreach (\Velvet\Core\MarketingAnalytics::EVENTS as $name): ?><option value="<?= $name ?>" <?= ($_GET['event'] ?? '') === $name ? 'selected' : '' ?>><?= velvet_marketing_escape(ucfirst(str_replace('_', ' ', $name))) ?></option><?php endforeach; ?></select></label>
<label class="marketing-check"><input type="checkbox" name="compare" value="1" style="width:auto" <?= ($_GET['compare'] ?? '') === '1' ? 'checked' : '' ?>> Compare the preceding period of the same length</label>
</div><button class="marketing-button">Update report</button></form>
<?php if ($analyticsError !== ''): ?><p class="marketing-notice" role="alert"><?= velvet_marketing_escape($analyticsError) ?></p><?php endif; ?>
<?php if ($report !== null): ?>
<p data-report-backend>Report source: <?= velvet_marketing_escape($report['backend']) ?>. <?= (int) $report['retained_unique_visitors'] ?> distinct measured visitors within retained raw data.</p>
<p data-measurement-capacity><?= (int) $report['capacity']['raw_events'] ?> of <?= (int) $report['capacity']['raw_limit'] ?> retained raw events; <?= (int) $report['capacity']['daily_totals'] ?> of <?= (int) $report['capacity']['daily_limit'] ?> daily totals. At either limit, new measurements pause until retention frees space; existing records are preserved.</p>
<?php if ($report['capacity']['legacy_events'] > 0): ?><p><?= (int) $report['capacity']['legacy_events'] ?> retained legacy events count toward storage usage and remain excluded from consented reports.</p><?php endif; ?>
<?php if ($report['capacity']['raw_events'] >= $report['capacity']['raw_limit'] * .9 || $report['capacity']['daily_totals'] >= $report['capacity']['daily_limit'] * .9): ?><p class="marketing-notice" role="alert">Measurement storage is near its supported limit. Run retention and review the retention periods before collecting further data.</p><?php endif; ?>
<div class="marketing-table-scroll" role="region" aria-label="Measured event comparison" tabindex="0"><table class="marketing-table" data-measurement-counts><caption>Measured events</caption><thead><tr><th scope="col">Event</th><th scope="col">Selected period</th><?php if (isset($report['previous'])): ?><th scope="col">Previous period</th><th scope="col">Change</th><?php endif; ?></tr></thead><tbody>
<?php foreach (\Velvet\Core\MarketingAnalytics::EVENTS as $name): $value = $report['counts'][$name] ?? 0; $previous = $report['previous']['counts'][$name] ?? 0; ?><tr><th scope="row"><?= velvet_marketing_escape(str_replace('_', ' ', $name)) ?></th><td><?= (int) $value ?></td><?php if (isset($report['previous'])): ?><td><?= (int) $previous ?></td><td><?= (int) ($value - $previous) ?></td><?php endif; ?></tr><?php endforeach; ?>
</tbody></table></div>
<h3>Ordered registration and purchase funnel</h3><p><?= velvet_marketing_escape($report['funnel_note']) ?></p><ol data-measurement-funnel><?php foreach ($report['retained_funnel'] as $name => $count): ?><li><?= velvet_marketing_escape(str_replace('_', ' ', $name)) ?>: <?= (int) $count ?></li><?php endforeach; ?></ol>
<h3>Gross purchase totals</h3><p>Each currency is reported separately. These measurements are not financial statements or net revenue.</p><ul><?php foreach ($report['gross_purchase_minor'] as $currency => $minor): ?><li><?= velvet_marketing_escape($currency) ?> <?= number_format($minor / 100, 2, '.', ',') ?></li><?php endforeach; ?></ul>
<h3>Top public pages</h3><table class="marketing-table"><thead><tr><th scope="col">Public path</th><th scope="col">Views</th></tr></thead><tbody><?php if ($report['top_paths'] === []): ?><tr><td colspan="2">No measured public pages in this period.</td></tr><?php endif; ?><?php foreach ($report['top_paths'] as $path => $count): ?><tr><th scope="row"><?= velvet_marketing_escape($path) ?></th><td><?= (int) $count ?></td></tr><?php endforeach; ?></tbody></table>
<form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="export_measurement_csv"><?php foreach (['start','end','campaign','referral','event'] as $key): ?><input type="hidden" name="<?= $key ?>" value="<?= velvet_marketing_escape($report['filters'][$key]) ?>"><?php endforeach; ?><button class="marketing-button">Export aggregate CSV</button></form>
<?php endif; ?></section>
<?php if (isset($analyticsConfiguration)): ?><section class="marketing-card" style="margin-top:22px" data-measurement-settings><h2>Measurement and retention</h2><form method="post" class="marketing-form"><?= csrf_field() ?><input type="hidden" name="action" value="save_analytics_configuration"><input type="hidden" name="analytics_revision" value="<?= velvet_marketing_escape($analyticsConfiguration['revision']) ?>"><label class="marketing-check"><input type="checkbox" name="analytics_enabled" value="1" style="width:auto" <?= $analyticsConfiguration['enabled'] ? 'checked' : '' ?>> Permit optional measurement after visitor consent</label><label>Raw event retention, days (7–365)<input type="number" name="retention_days" min="7" max="365" value="<?= (int) $analyticsConfiguration['retention_days'] ?>" required></label><label>Anonymous daily total retention, days (at least raw retention; at most 1,095)<input type="number" name="rollup_days" min="7" max="1095" value="<?= (int) $analyticsConfiguration['rollup_days'] ?>" required></label><p>Anonymous daily totals contain no visitor token or account identity. Distinct visitor and funnel metrics use retained raw events. Visitors can decline and remove their linked measurements from <a href="<?= e(base_url('privacy/choices.php')) ?>">Privacy choices</a>.</p><button class="marketing-button">Save measurement settings</button></form><form method="post" style="margin-top:18px"><?= csrf_field() ?><input type="hidden" name="action" value="run_analytics_maintenance"><button class="marketing-button">Run retention and reconciliation batch</button></form><p>For regular cleanup, schedule <code>php app/Console/run_analytics.php --limit=100</code>. Each run processes at most 250 source records, resumes its cursor and never sends messages or takes payments.</p></section><?php endif; ?>
